StyleGalleryDialog::StyleGalleryDialog(CWnd* owner,std::vector<services::ToolStyle> styles,int tool,std::function<void(size_t)> account):owner_(owner),styles_(std::move(styles)),account_(std::move(account)),initialTool_(tool){if(styles_.size()>32)throw std::runtime_error("Style preview limit32");}
INT_PTR StyleGalleryDialog::Run(){struct Template{DLGTEMPLATE t{};WORD menu=0,cls=0,title=0;}r;r.t.style=WS_POPUP|WS_CAPTION|WS_SYSMENU|DS_MODALFRAME|WS_CLIPCHILDREN;r.t.cx=440;r.t.cy=280;InitModalIndirect(&r.t,owner_);return DoModal();}
BOOL StyleGalleryDialog::OnInitDialog(){CDialog::OnInitDialog();dpi_=LayoutDpi(m_hWnd);BindText(*this,Text::StyleGallery);const DWORD style=WS_CHILD|WS_VISIBLE;filter_.Create(style|WS_TABSTOP|CBS_DROPDOWNLIST,CRect(),this,44970);help_.Create(Tr(Text::StyleGalleryHelp),style,CRect(),this);BindText(help_,Text::StyleGalleryHelp);list_.Create(style|WS_BORDER|WS_TABSTOP|LVS_ICON|LVS_SINGLESEL|LVS_SHOWSELALWAYS,CRect(),this,44971);list_.SetExtendedStyle(LVS_EX_DOUBLEBUFFER);ok_.Create(Tr(Text::ApplyStyle),style|WS_TABSTOP|BS_DEFPUSHBUTTON,CRect(),this,IDOK);BindText(ok_,Text::ApplyStyle);cancel_.Create(Tr(Text::Cancel),style|WS_TABSTOP,CRect(),this,IDCANCEL);BindText(cancel_,Text::Cancel);ApplyFont(*this,font_);PopulateFilter(initialTool_);Rebuild();Layout();CenterWindow(owner_);if(initAudit_){initAudit_(*this);job_.cancel=true;KillTimer(1);if(chosen<0)EndDialog(IDCANCEL);return FALSE;}Queue();return TRUE;}
HBITMAP StyleGalleryDialog::Bitmap(const core::Image& image){BITMAPINFO b{};b.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);b.bmiHeader.biWidth=image.width;b.bmiHeader.biHeight=-image.height;b.bmiHeader.biPlanes=1;b.bmiHeader.biBitCount=32;void* pixels=nullptr;HBITMAP bitmap=CreateDIBSection(nullptr,&b,DIB_RGB_COLORS,&pixels,nullptr,0);if(bitmap)memcpy(pixels,image.pixels.data(),image.pixels.size());return bitmap;}
void StyleGalleryDialog::PopulateFilter(int tool){filter_.ResetContent();filter_.AddString(Tr(Text::AllTools));filter_.SetItemData(0,DWORD_PTR(-1));int selected=0;std::set<int> tools;for(const auto& item:styles_)tools.insert(int(item.style.tool));for(int value:tools){const int n=filter_.AddString(Tr(ToolLabels()[value]));filter_.SetItemData(n,value);if(value==tool)selected=n;}filter_.SetCurSel(selected);}
int StyleGalleryDialog::Selected()const{const int item=list_.GetNextItem(-1,LVNI_SELECTED);return item>=0&&item<int(visible_.size())?visible_[item]:-1;}
void StyleGalleryDialog::Account(){size_t bytes=sizeof(*this)+visible_.capacity()*sizeof(int)+styles_.capacity()*sizeof(services::ToolStyle);for(const auto& s:styles_)bytes+=(s.name.GetLength()+s.style.font.GetLength())*sizeof(wchar_t);bytes+=visible_.size()*size_t(side_)*(side_*2/3)*4;if(account_)account_(bytes);}
void StyleGalleryDialog::Rebuild(int selected){++generation_;side_=std::clamp(Px(m_hWnd,96),64,192);const int tool=int(filter_.GetItemData(filter_.GetCurSel()));list_.SetImageList(nullptr,LVSIL_NORMAL);if(images_.GetSafeHandle())images_.DeleteImageList();images_.Create(side_,side_*2/3,ILC_COLOR32,32,1);list_.SetImageList(&images_,LVSIL_NORMAL);list_.DeleteAllItems();visible_.clear();ready_.clear();core::Image blank;blank.Create(side_,side_*2/3);for(size_t n=0;n<blank.pixels.size();n+=4){blank.pixels[n]=blank.pixels[n+1]=blank.pixels[n+2]=240;blank.pixels[n+3]=255;}CBitmap bitmap;bitmap.Attach(Bitmap(blank));for(size_t i=0;i<styles_.size();++i)if(tool<0||tool==int(styles_[i].style.tool)){const int item=int(visible_.size());visible_.push_back(int(i));ready_.push_back(false);list_.InsertItem(item,styles_[i].name,images_.Add(&bitmap,static_cast<CBitmap*>(nullptr)));if(int(i)==selected)list_.SetItemState(item,LVIS_SELECTED|LVIS_FOCUSED,LVIS_SELECTED|LVIS_FOCUSED);}list_.SetIconSpacing(side_+Px(m_hWnd,24),side_*2/3+Px(m_hWnd,44));ok_.EnableWindow(Selected()>=0);Account();}
void StyleGalleryDialog::Queue(){if(job_.Busy())return;size_t at=0;while(at<ready_.size()&&ready_[at])++at;if(at==ready_.size()){KillTimer(1);return;}const auto preset=styles_[visible_[at]];const auto generation=generation_;const int side=side_;job_.Start([preset,at,generation,side]{Result r;r.index=at;r.generation=generation;try{r.image=services::ToolStylePreview(preset,side);}catch(const std::exception& e){r.error.Format(L"%hs",e.what());}return r;});SetTimer(1,16,nullptr);}
void StyleGalleryDialog::OnTimer(UINT_PTR){auto r=job_.Take();if(r&&r->generation==generation_&&r->index<ready_.size()){ready_[r->index]=true;if(r->error.IsEmpty()){CBitmap bitmap;bitmap.Attach(Bitmap(r->image));if(bitmap.GetSafeHandle())images_.Replace(int(r->index),&bitmap,static_cast<CBitmap*>(nullptr));}else list_.SetItemText(int(r->index),0,styles_[visible_[r->index]].name+L" ("+Tr(Text::PreviewFailed)+L")");}Queue();}
void StyleGalleryDialog::OnFilter(){Rebuild();Queue();}
void StyleGalleryDialog::OnSelect(NMHDR*,LRESULT* result){*result=0;ok_.EnableWindow(Selected()>=0);}
void StyleGalleryDialog::OnDouble(NMHDR*,LRESULT* result){*result=0;OnOK();}
void StyleGalleryDialog::OnOK(){const int selection=Selected();if(selection<0)return;chosen=selection;job_.cancel=true;KillTimer(1);EndDialog(IDOK);}
void StyleGalleryDialog::OnCancel(){job_.cancel=true;KillTimer(1);CDialog::OnCancel();}
void StyleGalleryDialog::Layout(){MONITORINFO m{sizeof(m)};GetMonitorInfo(MonitorFromWindow(m_hWnd,MONITOR_DEFAULTTONEAREST),&m);if(workAreaAudit_.cx>0){m.rcWork.right=m.rcWork.left+workAreaAudit_.cx;m.rcWork.bottom=m.rcWork.top+workAreaAudit_.cy;}CRect decoration(0,0,0,0);AdjustClientRect(decoration,*this);const int gap=Px(m_hWnd,10),row=Px(m_hWnd,30),width=std::min(Px(m_hWnd,740),int(m.rcWork.right-m.rcWork.left)-decoration.Width()-gap*2),height=std::min(Px(m_hWnd,520),int(m.rcWork.bottom-m.rcWork.top)-decoration.Height()-gap*2);filter_.MoveWindow(gap,gap,std::min(Px(m_hWnd,260),width-gap*2),Px(m_hWnd,350));help_.MoveWindow(gap,row+gap*2,width-gap*2,row*2);const int top=row*3+gap*3,bottom=height-row-gap;list_.MoveWindow(gap,top,width-gap*2,std::max(1,bottom-gap-top));const int button=std::max(Px(m_hWnd,90),std::max(TextWidth(ok_,Tr(Text::ApplyStyle),20),TextWidth(cancel_,Tr(Text::Cancel),20)));ok_.MoveWindow(width-gap*2-button*2,bottom,button,row);cancel_.MoveWindow(width-gap-button,bottom,button,row);CRect window(0,0,width,height);AdjustClientRect(window,*this);SetWindowPos(nullptr,0,0,window.Width(),window.Height(),SWP_NOMOVE|SWP_NOZORDER);Invalidate(TRUE);}
LRESULT StyleGalleryDialog::OnDpiChanged(WPARAM,LPARAM r){ScaleDialog(*this,font_,dpi_,r);const int selected=Selected();Rebuild(selected);Layout();Queue();return 0;}
LRESULT StyleGalleryDialog::OnLanguageChanged(WPARAM,LPARAM){const int tool=int(filter_.GetItemData(filter_.GetCurSel())),selected=Selected();RefreshBoundText(m_hWnd);PopulateFilter(tool);Rebuild(selected);Layout();Queue();return 0;}
